  $('#sheet-form').addEventListener('submit',async e=>{e.preventDefault();if(sheetSync.busy||sheetSync.worker||state.animation){$('#sheet-feedback').textContent='รอการซิงก์หรือ Animation จบสักครู่ แล้วลองอีกครั้ง';return}const url=$('#sheet-url').value.trim(),button=$('#sheet-connect-btn');button.disabled=true;sheetSync.busy=true;$('#sheet-feedback').textContent='กำลังตรวจสอบชีท…';try{const data=await fetchSnapshot(url);sheetSync.generation++;sheetSync.url=url;sheetSync.initialized=false;sheetSync.knownEventIds.clear();useDemoData();state.shipments=data.shipments.filter(row=>row['Shipment ID']).map(row=>structuredClone(initialShipments.find(item=>item.id===String(row['Shipment ID']))||{id:String(row['Shipment ID']),direction:'',docs:[],events:[],route:'',progress:0}));state.selected=state.shipments[0].id;localStorage.setItem('freight-sheet-url',url);sheetSync.syncFailures=0;sheetSync.nextSyncAt=0;applySheetSnapshot(data);startSyncTimer();showLastSync();$('#sheet-dialog').close();toast('Google Sheet connected')}catch(error){$('#sheet-feedback').textContent=error.message}finally{button.disabled=false;sheetSync.busy=false}});
